"""Gera três guias de estudo em PDF. Dependência: reportlab."""
from pathlib import Path
from xml.sax.saxutils import escape
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, KeepTogether
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.pagesizes import A4

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'entrega'
S = getSampleStyleSheet()
S.add(ParagraphStyle(name='BodyCPU',fontName='Helvetica',fontSize=10.5,leading=15,spaceAfter=9))
S.add(ParagraphStyle(name='SmallCPU',fontName='Helvetica',fontSize=8.5,leading=11,spaceAfter=6,textColor=colors.HexColor('#41566A')))
S.add(ParagraphStyle(name='CellCPU',fontName='Helvetica',fontSize=9.2,leading=12.5))
S.add(ParagraphStyle(name='QCPU',fontName='Helvetica-Bold',fontSize=11,leading=14,spaceBefore=8,spaceAfter=5,textColor=colors.HexColor('#173B57')))
S['Title'].fontSize=23; S['Title'].leading=27; S['Title'].alignment=0
S['Heading2'].textColor=colors.HexColor('#173B57')
class StudyDoc(SimpleDocTemplate):
    def afterFlowable(self, flowable):
        if isinstance(flowable, Paragraph) and flowable.style.name == 'Title':
            key = f'page-{self.page}'
            self.canv.bookmarkPage(key)
            self.canv.addOutlineEntry(flowable.getPlainText(), key, 0)

class Guide:
    def __init__(self,name,label): self.name=name; self.label=label; self.story=[]
    def page(self,title,subtitle):
        if self.story: self.story.append(PageBreak())
        self.story.append(Paragraph('ARQUITETURA CPU  |  MATERIAL DE ESTUDO  |  25/11/2026',S['SmallCPU']))
        self.story.append(Paragraph(title,S['Title']))
        self.story.append(Paragraph(subtitle,S['SmallCPU'])); self.story.append(Spacer(1,9))
    def p(self,text): self.story.append(Paragraph(text,S['BodyCPU']))
    def h(self,text): self.story.append(Paragraph(text,S['Heading2']))
    def box(self,text):
        t=Table([[Paragraph(text,S['BodyCPU'])]],colWidths=[507]); t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),colors.HexColor('#EAF1F6')),('BOX',(0,0),(-1,-1),.5,colors.HexColor('#B9CBD9')),('LEFTPADDING',(0,0),(-1,-1),12),('RIGHTPADDING',(0,0),(-1,-1),12),('TOPPADDING',(0,0),(-1,-1),10),('BOTTOMPADDING',(0,0),(-1,-1),4)])); self.story.extend([t,Spacer(1,10)])
    def table(self,rows,widths):
        t=Table([[Paragraph(str(v),S['CellCPU']) for v in r] for r in rows],colWidths=widths,repeatRows=1,hAlign='LEFT')
        t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#DAE7F0')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F5F7FA')]),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),.6,colors.HexColor('#AABBC8')),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)])); self.story.extend([t,Spacer(1,10)])
    def qa(self,n,q,a,ref):
        self.story.append(KeepTogether([Paragraph(f'{n}. {q}',S['QCPU']),Paragraph(a,S['BodyCPU']),Paragraph('Onde mostrar: '+ref,S['SmallCPU'])]))
    def ref(self,text): self.story.append(Paragraph('Conferência nos fontes: '+text,S['SmallCPU']))
    def save(self):
        def footer(c,d):
            c.setStrokeColor(colors.HexColor('#B9CBD9')); c.line(44,40,551,40)
            c.setFont('Helvetica',8); c.setFillColor(colors.HexColor('#41566A')); c.drawString(44,27,self.label); c.drawRightString(551,27,str(d.page))
        StudyDoc(str(OUT/self.name),pagesize=A4,leftMargin=44,rightMargin=44,topMargin=34,bottomMargin=53,title=self.label,author='Projeto Arquitetura CPU').build(self.story,onFirstPage=footer,onLaterPages=footer)
        print(OUT/self.name)

# DOCUMENTO 1
G=Guide('01 - Do codigo a placa e explicacao da demo.pdf','CPU 16 bits | Do código à placa e explicação da demo')
G.page('1. Do código ao circuito','O que o computador prepara e o que a FPGA executa')
G.p('A DE2-115 contém uma FPGA Cyclone IV E. No projeto, descrevemos uma CPU de 16 bits em VHDL e usamos o Quartus para configurar os recursos internos da FPGA: lógica, registradores, memória e ligações. Depois da programação, esses circuitos executam as instruções guardadas na RAM.')
G.table([['Arquivo / etapa','Papel no projeto'],['VHDL (.vhd)','Descreve o circuito: ULA, registradores, memória, controle e interface com botões/LEDs.'],['MIF (.mif)','Define as palavras iniciais da memória: instruções e dados do programa.'],['QPF + QSF + SDC','Definem projeto, dispositivo, fontes, pinos, padrões elétricos e restrições de tempo.'],['Compilação Quartus','Sintetiza, posiciona e conecta a lógica; analisa timing e gera a imagem de configuração.'],['SOF + USB-Blaster','O Programmer envia a imagem .sof pela interface JTAG para configurar a FPGA.']],[145,362])
G.box('<b>Exemplo:</b> demo.sof contém a configuração da CPU e a inicialização de memória correspondente à demo. A primeira palavra do programa é 5203, que representa ADDI R1,R0,3.')
G.p('A CPU não recebe o texto VHDL pela porta USB a cada instrução. O computador transmite o SOF durante a configuração. Depois disso, o clock de 50 MHz da placa fornece as bordas usadas pelo circuito, e os controles manuais autorizam ou pausam o avanço.')
G.h('O que muda ao editar cada parte')
G.p('Editar VHDL altera a arquitetura do circuito. Editar o MIF altera o programa ou os dados iniciais. Em ambos os casos, é necessário produzir uma imagem de programação que incorpore a mudança. Alterar um arquivo no computador não modifica a configuração já carregada na placa.')
G.p('A programação por SOF é volátil. Depois de desligar a placa, carregue o SOF de novo para repetir a demonstração. O teste do projeto não inclui gravar uma imagem persistente na memória de configuração.')
G.ref('cpu_de2_115.qsf; cpu_de2_115.sdc; top_de2_115.vhd; memory.vhd; cpu_test.mif.')

G.page('2. Entradas e saídas da placa','O top conecta o mundo físico à CPU')
G.table([['Caminho','O que acontece'],['KEY0 / KEY1 / SW0 → board_controls','Tratamento de reset, sincronização e filtro; produção de reset, clock_enable e running.'],['CLOCK_50 → controles e CPU','Um clock comum de 50 MHz. KEY1 autoriza um ciclo; ele não substitui o clock.'],['board_controls → cpu','Reset reinicia; clock_enable autoriza a borda que avança a execução.'],['cpu → top_de2_115','PC, instrução, operandos, resultados, estado e falha retornam como sinais de observação.'],['SW3..1 → seleção → HEX/LEDR','O seletor escolhe o valor exibido. Não altera registradores nem executa instruções.']],[210,297])
G.h('Quem liga cada sinal a um terminal físico')
G.p('Em top_de2_115.vhd, portas como KEY(0), SW(0) e HEX0 representam sinais do circuito. Em cpu_de2_115.qsf, cada porta recebe uma posição de pino e um padrão elétrico. Exemplos: CLOCK_50 está em PIN_Y2; KEY0 em PIN_M23; KEY1 em PIN_M21; SW0 em PIN_AB28. O QSF é a ligação entre o nome lógico e o terminal da FPGA.')
G.table([['Controle / indicador','Uso'],['KEY0 / KEY1','Reset ativo ao pressionar / um ciclo por pressão no manual.'],['SW0 / LEDG6','0 manual; 1 contínuo. LEDG6 indica o modo filtrado.'],['HEX7..4 / HEX3..0','PC / valor selecionado. HEX7 e HEX3 são os dígitos mais significativos.'],['LEDR15..0 / LEDR16 / LEDR17','Valor em binário / reset ativo / falha de endereço retida.'],['LEDG3..0 / LEDG4 / LEDG5','Estado em binário / Zero / Overflow.'],['LEDG7 / LEDG8','Pulsos de escrita no banco / memória. Não exigir observação visual desses pulsos.']],[175,332])
G.p('A função seven_segment converte cada grupo de quatro bits em sete segmentos. As saídas são ativas em zero: um bit 0 acende o segmento correspondente. O dígito b ou d tem aparência minúscula no display.')
G.ref('top_de2_115.vhd: portas, seven_segment e atribuições LEDR/LEDG; cpu_de2_115.qsf.')

G.page('3. O interior da CPU','Controle decide a etapa; datapath calcula e armazena')
G.table([['Bloco','Função e ligação'],['control_unit + decoder','O decoder classifica o opcode. A máquina de estados escolhe quando ler, calcular, gravar e mudar o PC.'],['PC + IR','PC guarda o endereço usado pela execução. IR mantém a instrução enquanto suas várias etapas acontecem.'],['Banco R0–R7','Duas leituras e uma escrita. R0 fornece zero; R1–R7 guardam valores de 16 bits.'],['A / B → ULA → ALUOut','A e B retêm operandos. A ULA calcula. ALUOut retém o resultado para a etapa seguinte.'],['REM → RAM → RDM','REM guarda endereço de 10 bits; RAM lê/grava palavras de 16 bits; RDM retém o dado lido.']],[170,337])
G.p('A CPU é multiciclo: uma instrução atravessa várias etapas e reutiliza os mesmos blocos. O projeto usa uma memória unificada para instruções e dados, com acesso serializado pelo controle. A RAM possui 1024 palavras de 16 bits, totalizando 2048 bytes. Um incremento do PC avança uma palavra, não um byte.')
G.h('O que acontece em uma borda de clock')
G.p('A lógica combinacional, como ULA e seletores, responde às entradas. Os registradores capturam valores na borda de subida quando suas habilitações permitem. Se A/B e ALUOut forem habilitados na mesma borda, ALUOut ainda recebe o cálculo dos operandos anteriores. Por isso a CPU separa captura de operandos e captura do resultado em ciclos distintos.')
G.h('Pausa, sincronização e repique')
G.p('board_controls usa dois flip-flops para sincronizar sinais externos e um filtro de estabilidade para passo/modo. Com 500000 ciclos a 50 MHz, o filtro equivale a cerca de 10 ms. Uma pressão válida produz um pulso de clock_enable; segurar KEY1 não repete passos. No contínuo, a habilitação permanece ativa.')
G.p('O reset é assertado de forma assíncrona e liberado por dois estágios sincronizados. Ele tem prioridade sobre a pausa. O circuito mantém o clock em funcionamento mesmo quando a CPU está parada; os enables bloqueiam mudanças de estado e acessos à RAM. Sincronização reduz o risco de metastabilidade, mas simulação digital não mede esse risco físico.')
G.ref('cpu.vhd; datapath.vhd; register_file.vhd; control_unit.vhd; board_controls.vhd.')

G.page('4. O programa da demo','Três somas, uma escrita e uma releitura')
G.p('A demo usa R1 como contador, R2 como incremento e R3 como acumulador. R4 recebe o valor relido da RAM. Os endereços e códigos abaixo estão em hexadecimal; o endereço de dados 0010 corresponde a 16 decimal.')
G.table([['End.','Código','Instrução / efeito'],['0000','5203','ADDI R1,R0,3: contador começa em 3.'],['0001','5401','ADDI R2,R0,1: incremento vale 1.'],['0002','5600','ADDI R3,R0,0: acumulador começa em 0.'],['0003','06D0','ADD R3,R3,R2: acumula mais 1.'],['0004','1250','SUB R1,R1,R2: diminui o contador.'],['0005','8201','BEQ R1,R0,1: se R1=0, salta para 0007.'],['0006','A003','JMP 3: volta para a soma.'],['0007','7610','ST R3,16(R0): grava R3 em Mem[0010].'],['0008','6810','LD R4,16(R0): lê Mem[0010] para R4.'],['0009','A009','JMP 9: repete o salto para o próprio endereço.']],[48,65,394])
G.table([['Momento','R1: contador','R3: soma'],['Após inicializar','3','0'],['Após a primeira soma/subtração','2','1'],['Após a segunda soma/subtração','1','2'],['Após a terceira soma/subtração','0','3']],[267,120,120])
G.p('No BEQ em 0005, o PC já avançou para 0006 durante a busca. Quando R1=0, o destino é 0006 + 1 = 0007. Nas duas primeiras voltas, o BEQ não toma o desvio e o JMP em 0006 retorna a 0003.')
G.box('<b>Resultado esperado:</b> R3=R4=0003 e Mem[0010]=0003. A escrita em 0010 preserva as instruções em 0000–0009. Assim o reset permite repetir o programa sem destruir a primeira instrução.')
G.ref('cpu_test.mif; docs/isa.md; tests/tb_cpu.vhd.')

G.page('5. A primeira instrução por dentro','Por que cinco pressões completam ADDI R1,R0,3')
G.p('Comece após KEY0, em manual. A palavra 5203 contém opcode 5 (ADDI), destino R1, origem R0 e imediato +3. O extensor transforma os seis bits do imediato em um valor de 16 bits; a ULA calcula 0000 + 0003.')
G.table([['Passo','Ação na borda autorizada','Estado depois / observação'],['Reset','Zera PC, IR e registradores; preserva RAM.','0; PC=0000 e IR=0000.'],['1','FETCH0 solicita leitura da RAM no endereço do PC.','1; fetched=5203. IR ainda é 0000.'],['2','FETCH1 captura fetched no IR e carrega PC+1.','2; IR=5203, PC=0001.'],['3','DECODE captura operandos no caminho de dados.','3; execução ADDI preparada.'],['4','EXEC captura a soma em ALUOut.','9; ALUOut=0003. R1 ainda aguarda a escrita.'],['5','WB escreve o retorno no banco, destino R1.','0; R1=0003. Pronto para buscar a próxima instrução.']],[50,270,187])
G.h('Como os testes enxergam essa sequência')
G.p('Com SW3..1=000, HEX3..0 mostra IR. Depois da segunda pressão, deve aparecer 5203. Na quarta pressão, mude para 011: aparece ALUOut=0003. Mude para 110: o retorno ao banco também vale 0003. A quinta pressão conclui a escrita.')
G.p('Os LEDs LEDG3..0 mostram o estado em binário. Estado 9 é 1001: LEDG3 e LEDG0 acesos. Essa indicação descreve a etapa aguardando a próxima borda. Ver estado 9 não significa que a escrita já ocorreu.')
G.box('<b>Os dois valores 0003 do roteiro:</b> aqui, 0003 inicializa o contador R1. No final, 0003 no RDM é o resultado acumulado depois da escrita e da releitura da RAM. O número é igual, mas a evidência é diferente.')
G.p('O banco não possui um seletor externo para consultar R1–R7 individualmente. A/B mostram operandos retidos, e o retorno mostra o dado disponível para escrita naquele estado. Em simulação, os testbenches acompanham também endereço e habilitação de escrita.')
G.ref('decoder.vhd; immediate_extender.vhd; control_unit.vhd; datapath.vhd; tests/tb_top_de2_115.vhd.')

G.page('6. Memória e laço final','O que o teste comprova ao mostrar 0003 no RDM')
G.p('No ST em 0007, o controle captura R0 como base e R3 como dado. Em ADDR, calcula 0+16 e guarda o endereço no REM. Em WRITE_MEM, um passo autorizado grava 0003 em Mem[0010]. Enquanto a CPU aguarda esse passo, a escrita permanece bloqueada.')
G.p('No LD em 0008, o controle calcula o mesmo endereço. READ_MEM produz o dado na saída registrada da RAM; LATCH_RDM captura esse dado no RDM; WB escreve RDM em R4. Essas etapas respeitam a latência da memória síncrona.')
G.table([['Seleção SW3..1 no laço final','Valor','Explicação'],['000: IR','A009','Instrução JMP 9.'],['001: A / 010: B','0000','Operandos retidos após o LD; o JMP não os recarrega.'],['011: ALUOut','0010','Último endereço calculado: 16 decimal.'],['100: RDM','0003','Dado recuperado da memória pelo LD.'],['101: fetched','A009','Última palavra lida na busca do salto.'],['110: retorno','0010','Fora de WB, o seletor padrão aponta para ALUOut.'],['111: endereço RAM','0009','No estado 0 do laço, o endereço vem do PC=0009.']],[245,60,202])
G.p('O laço final não é uma instrução HALT. A CPU continua buscando e executando JMP 9. O PC passa de 0009 para 000A ao capturar a instrução e volta para 0009 ao executar o salto. Por isso o roteiro manda comparar o PC junto com o estado.')
G.h('O que podemos concluir')
G.p('Resultados corretos na demo verificam um caminho integrado: busca, decodificação, soma/subtração, BEQ, JMP, escrita e leitura da RAM, além de pausa e reset. A tabela de seletores verifica a observação externa. O teste não cobre sozinho AND, OR, SLT, BNE, overflow e todos os erros de endereço.')
G.p('Para esses casos, o projeto inclui p1 a p4 e top_memory. LEDG4/5 refletem a operação combinacional atual; não guardam um histórico de flags. LEDR17 indica falha de endereço e deve permanecer apagado na demo.')
G.ref('control_unit.vhd; datapath.vhd; cpu_test.mif; tests/tb_top_de2_115.vhd.')

G.page('7. Ler código e defender o teste','Termos úteis e limites da evidência')
G.table([['Termo','Significado no projeto'],['entity / architecture','Interface do módulo / descrição de seu circuito interno.'],['port map','Conecta portas de uma instância aos sinais do circuito que a contém.'],['generic','Parâmetro de elaboração, como init_file ou debounce_cycles; não é um botão de execução.'],['process(all)','Lógica combinacional recalculada quando entradas relevantes mudam.'],['rising_edge(clk)','Borda em que o armazenamento síncrono pode capturar dados.'],['write_enable / clock_enable','Autorização de captura local / autorização global para avançar a CPU.'],['signal e atribuição &lt;=','Ligação/estado no modelo VHDL; atribuições de sinais seguem a semântica de atualização da simulação.'],['assert no testbench','Compara o observado com uma condição esperada e relata falha.']],[160,347])
G.h('Um exemplo de explicação oral')
G.p('“Descrevemos uma CPU multiciclo de 16 bits. O Quartus transforma os fontes em uma configuração para a FPGA. O top recebe os botões e switches, trata os controles e mostra sinais internos nos LEDs e displays. Na demo, somamos 1 três vezes, gravamos o resultado na RAM e lemos para R4. O RDM em 0003 permite observar a releitura. O JMP final mantém o programa em um endereço conhecido.”')
G.h('O que foi verificado e o que depende da bancada')
G.p('Na revisão local de 25/11, as 16 suítes GHDL passaram. O projeto contém evidências anteriores de 35 simulações ModelSim e relatórios Quartus com timing positivo. Essas evidências não substituem fotos, valores e resultados obtidos na placa específica do laboratório.')
G.p('Não há confirmação registrada de aprovação de todos os testes físicos. Ao apresentar, diferencie: comportamento previsto no código, comportamento confirmado por simulação e resultado realmente observado pela equipe. Não afirme que overflow foi testado usando apenas a demo.')
G.p('Leitura sugerida dos fontes: top_de2_115 → board_controls → cpu → control_unit e datapath → componentes. Para acompanhar o programa, mantenha cpu_test.mif ao lado e use o roteiro de bancada já existente em entrega/.')
G.ref('Fontes locais do checkout fd9d217 e revisão documental de 25/11/2026. Este guia descreve o projeto, não um gabarito do professor.')
G.save()

# DOCUMENTO 2
Q=Guide('02 - Perguntas e respostas para arguicao.pdf','CPU 16 bits | Perguntas e respostas para arguição')
Q.page('1. Arquitetura e visão geral','Perguntas prováveis para treinar; não são perguntas confirmadas do professor')
Q.p('Use as respostas como base e treine apontar o trecho correspondente no código. Quando perguntarem sobre resultados na placa, acrescente apenas o que a equipe realmente observou. Os exemplos abaixo descrevem a implementação atual.')
Q.qa(1,'O que vocês construíram?','Uma CPU de 16 bits em VHDL, com banco de oito registradores, ULA, RAM e controle multiciclo. O top adapta essa CPU à DE2-115 com reset, passo manual, execução contínua e observação em LEDs e displays.','cpu.vhd e top_de2_115.vhd.')
Q.qa(2,'O que significa “16 bits”?','As instruções, os dados e os registradores principais têm 16 bits. Isso não obriga todos os sinais a terem essa largura: o banco usa índices de 3 bits e a RAM usa endereço físico de 10 bits.','register_file.vhd; memory.vhd; datapath.vhd.')
Q.qa(3,'Por que a CPU é multiciclo?','O controle divide uma instrução em busca, decodificação e etapas específicas. A mesma ULA atende cálculos de dados e endereços em momentos distintos. Sem pausa ou falha, ADD/ADDI usam 5 ciclos, LD 7, ST 5, BEQ/BNE 4 e JMP 3.','control_unit.vhd: state_t e case state.')
Q.qa(4,'A arquitetura usa memória separada para instruções e dados?','O projeto usa RAM unificada: instruções e dados compartilham o espaço de 1024 palavras. O controle alterna o endereço entre PC e REM. Os acessos de busca e de dados acontecem em etapas diferentes.','datapath.vhd: mem_address; memory.vhd.')
Q.qa(5,'Isso é um processador Nios II?','A CPU é própria, implementada pelos módulos VHDL do repositório, com a ISA documentada no projeto. O uso do Quartus e da placa Intel/Altera não transforma o circuito em Nios II.','cpu.vhd; decoder.vhd; docs/isa.md.')

Q.page('2. VHDL e armazenamento','Perguntas sobre a descrição do circuito')
Q.qa(6,'Qual a diferença entre lógica combinacional e sequencial?','A ULA calcula a partir dos operandos atuais, sem armazenar histórico. PC, IR, A/B e ALUOut retêm valores e capturam novos dados em bordas de clock autorizadas. Reset assíncrono é uma condição de atualização independente da borda.','alu.vhd; pc.vhd; alu_out.vhd.')
Q.qa(7,'O PC soma 1 dentro de pc.vhd?','Não. O módulo PC carrega next_pc quando pc_write permite. O datapath calcula PC+1, destino relativo e destino de JMP; um seletor escolhe qual deles alimentar no PC.','pc.vhd; datapath.vhd: pc_plus_one e pc_next.')
Q.qa(8,'Por que manter o IR se a memória já contém a instrução?','Durante a execução, a saída da RAM pode mudar, inclusive por uma leitura de dados. O IR conserva a palavra em execução e fornece campos estáveis para a decodificação até a próxima captura.','instruction_register.vhd; datapath.vhd.')
Q.qa(9,'Por que separar A/B e ALUOut?','A/B retêm os operandos obtidos do banco. Em outra borda, ALUOut captura o cálculo. Em uma mesma borda, os registradores usam os valores anteriores às atualizações; tentar capturar tudo junto não calcula automaticamente com os novos operandos.','reg_a.vhd; reg_b.vhd; alu_out.vhd.')
Q.qa(10,'Como garantem que R0 não muda?','O array físico contém R1 a R7. Leituras com endereço zero retornam uma constante zero, e a escrita só ocorre se write_addr for diferente de 000. Não dependemos de uma rotina de software para zerar R0.','register_file.vhd: register_array e condição de escrita.')
Q.qa(11,'O que um port map e um generic fazem?','port map liga portas da instância a sinais. generic configura uma escolha durante elaboração, como o arquivo inicial de memória ou a duração do debounce. Esses parâmetros não são modificados por SW0 durante a execução.','top_de2_115.vhd: instâncias controls e processor.')

Q.page('3. Instruções e ULA','Campos da ISA e cálculos que podem aparecer na arguição')
Q.qa(12,'Como decodificar 5203?','O opcode 0101 indica ADDI; Ri=001 escolhe R1; Rj=000 escolhe R0; imediato 000011 vale +3. Portanto, executa R1 ← R0 + 3. O destino só muda na etapa WB.','cpu_test.mif; decoder.vhd; datapath.vhd.')
Q.qa(13,'Quais são os três formatos de instrução?','R: opcode de 4 bits, Ri/Rj/Rk de 3 bits cada e 3 bits ignorados. I: opcode de 4, Ri/Rj de 3 e imediato de 6. J: opcode de 4 e endereço de 12 bits. Todos totalizam 16 bits.','docs/isa.md; extração dos campos em datapath.vhd.')
Q.qa(14,'Por que o imediato vai de -32 a 31?','São seis bits em complemento de dois: -2 elevado a 5 até 2 elevado a 5 menos 1. O extensor replica o bit de sinal. 111111 vira FFFF (-1); 100000 vira FFE0 (-32). Preencher com zeros mudaria o valor dos negativos.','immediate_extender.vhd.')
Q.qa(15,'Como Zero e Overflow diferem?','Zero indica resultado igual a 0000. Overflow indica que uma soma/subtração signed não cabe em 16 bits. Por exemplo, 7FFF+1 produz 8000 e Overflow=1. As flags são combinacionais; ALUOut armazena o resultado, não as flags.','alu.vhd; top_de2_115.vhd: LEDG4/5.')
Q.qa(16,'Overflow interrompe a execução?','Não. O resultado é truncado em 16 bits, sem saturação ou exceção por overflow. A flag fica disponível para observação. A parada por address_fault é outro mecanismo, associado a acesso fora da RAM.','alu.vhd; datapath.vhd: fault_latched.')
Q.qa(17,'SLT é signed? E um opcode inválido?','SLT compara signed(A) com signed(B), produzindo 0001 ou 0000. Opcodes de instrução B a F são ignorados: a busca já avançou o PC, e DECODE retorna a FETCH0 sem escrita. Isso é diferente dos seletores internos não usados da ULA.','alu.vhd; decoder.vhd; control_unit.vhd.')

Q.page('4. Memória, saltos e proteção','Explique o caminho do endereço e do dado')
Q.qa(18,'Qual é a capacidade da RAM?','1024 palavras de 16 bits: 16384 bits, ou 2048 bytes. O endereço seleciona uma palavra inteira. Os 10 bits da porta endereçam 0000–03FF; o PC e o endereço efetivo são tratados em 16 bits antes dessa porta.','memory.vhd; datapath.vhd.')
Q.qa(19,'Por que LD precisa de vários estados?','ADDR calcula e captura o endereço; READ_MEM faz a leitura síncrona; LATCH_RDM captura o dado que a RAM entregou após a borda anterior; WB escreve no banco. Antes disso houve FETCH0, FETCH1 e DECODE.','control_unit.vhd; memory.vhd; memory_data_register.vhd.')
Q.qa(20,'O reset limpa a memória?','Não. A RAM não tem porta de reset. KEY0 zera registradores e controle, mas preserva as palavras gravadas. Reprogramar o SOF restaura a imagem inicial. No MIF de teste top_memory isso permite distinguir dado original de dado escrito.','memory.vhd; board_controls.vhd; tests/tb_top_de2_115.vhd.')
Q.qa(21,'O que acontece ao acessar 0400?','Está fora da RAM. O datapath verifica os bits altos antes de permitir acesso. Bloqueia efeitos inválidos, registra address_fault e informa halt ao controle. A CPU permanece parada até reset. Um JMP pode primeiro colocar 0400 no PC; a falha surge na tentativa de busca.','datapath.vhd: invalid_address, run_ok e fault_latched.')
Q.qa(22,'Como calculam o destino de BEQ?','A condição compara Ri e Rj. Se forem iguais, o alvo é o PC já incrementado mais o imediato com sinal. Na demo, BEQ em 0005 com imediato 1 salta para 0007, porque a busca deixou PC=0006. BNE usa a condição oposta.','decoder.vhd; control_unit.vhd: CMP; datapath.vhd: branch_target.')
Q.qa(23,'E o JMP com endereço de 12 bits?','O datapath acrescenta quatro zeros à esquerda e carrega o valor no PC. O campo de 12 bits permite expressar alvos maiores que a RAM física; o mecanismo de falha continua limitando buscas à faixa válida.','datapath.vhd: jmp_target; control_unit.vhd: DECODE.')

Q.page('5. Placa, botões e timing','Perguntas sobre a passagem da simulação para o hardware')
Q.qa(24,'KEY1 é o clock da CPU?','Não. CLOCK_50 continua sendo o clock único. Após sincronização e filtro, KEY1 produz um pulso de clock_enable que autoriza um ciclo. Isso permite pausar sem criar um clock derivado do botão.','board_controls.vhd; top_de2_115.vhd.')
Q.qa(25,'Para que servem sincronizador e debounce?','Os sinais externos não têm relação fixa com CLOCK_50. Dois estágios reduzem o risco de metastabilidade na transferência. O debounce exige estabilidade por vários ciclos para filtrar repiques. São problemas diferentes; um recurso não substitui o outro.','board_controls.vhd: meta/synced e filters.')
Q.qa(26,'Por que 500000 ciclos?','A 50 MHz, cada ciclo dura 20 ns. 500000 × 20 ns = 10 ms. O atraso de resposta inclui também os estágios de sincronização e a lógica de controle. Segurar KEY1 gera um passo; é preciso soltar para rearmar.','board_controls.vhd: debounce_cycles e armed.')
Q.qa(27,'O que o SDC garante?','Ele informa um clock de 20 ns e as exceções adotadas para entradas assíncronas e indicadores sem clock externo de amostragem. O Timing Analyzer analisa os caminhos sob essas restrições. Uma análise positiva depende de as restrições representarem o circuito real.','cpu_de2_115.sdc; entrega/evidencias/cpu_de2_115.sta.summary.')
Q.qa(28,'O QSF é só uma lista de pinos?','Ele também define dispositivo, entidade de topo, fontes, padrão VHDL, MIF, SDC, diretório de saída e padrões elétricos. Pinagem correta e tensão compatível são parte da integração com a placa.','cpu_de2_115.qsf.')
Q.qa(29,'Por que o display acende com zero e LEDG7 parece apagado?','HEX usa segmentos ativos em nível baixo. Já LEDG7 mostra um pulso de escrita, sem alongamento para leitura humana. Mesmo no passo manual, a habilitação dura um ciclo do clock; a confirmação deve usar valores armazenados.','top_de2_115.vhd: seven_segment e LEDG; cpu.vhd.')

Q.page('6. Perguntas sobre a demo','Respostas ligadas aos valores que vocês mostram na bancada')
Q.qa(30,'O que a demo calcula?','Inicializa R1=3, R2=1 e R3=0. Soma R2 em R3 e decrementa R1 três vezes. Quando R1 chega a zero, grava R3 em Mem[16], lê para R4 e repete JMP 9. O resultado esperado é R3=R4=Mem[16]=3.','cpu_test.mif; docs/isa.md.')
Q.qa(31,'O primeiro 0003 já prova as três somas?','Não. Após a primeira ADDI, 0003 em ALUOut é o valor usado para inicializar o contador. O 0003 no RDM ao final é a releitura da memória depois das somas e do ST. Identificamos a evidência pelo seletor, PC e estado.','tests/tb_top_de2_115.vhd; cpu_test.mif.')
Q.qa(32,'Por que ALUOut mostra 0010 no final?','O último cálculo armazenado na ULA é o endereço do LD: R0+16. Em hexadecimal, 16 é 0010. O dado recuperado da RAM está no RDM, cuja seleção é 100; ALUOut não precisa conter o resultado acumulado no fim.','datapath.vhd: alu_out_unit; top_de2_115.vhd: seletor.')
Q.qa(33,'Por que o PC oscila entre 0009 e 000A?','Em FETCH1, o PC incrementa ao capturar A009. Em DECODE, JMP 9 recarrega 0009. Para comparar um ponto fixo, pausamos e avançamos até estado 0. Nesse ponto o PC deve ser 0009.','control_unit.vhd: FETCH1 e DECODE.')
Q.qa(34,'Posso ver qualquer registrador com os switches?','Não há acesso direto a R0–R7 no seletor externo. Podemos ver operandos A/B, ALUOut, RDM, IR, retorno e endereço. Para provar uma escrita, observamos o retorno no estado correto e a execução posterior, ou usamos os monitores do testbench.','top_de2_115.vhd: select_sync; cpu.vhd: portas de observação.')
Q.qa(35,'Como provar que a memória recebeu o resultado?','O programa faz ST e depois LD do mesmo endereço. O RDM em 0003 confirma a releitura, e a simulação também confere escrita, destino e conteúdo. A demonstração deve usar o SOF correto e começar de um estado conhecido.','cpu_test.mif; tests/tb_cpu.vhd.')

Q.page('7. Testes, limitações e treino','Responda com evidências do projeto, sem prometer cobertura total')
Q.qa(36,'Simulação aprovada significa placa aprovada?','Não. A simulação verifica o modelo digital nos cenários aplicados. A compilação/timing verifica a implementação sob as restrições. A bancada verifica ainda programação, pinos, controles e comportamento observado na unidade física.','tests/; entrega/evidencias/; roteiro de testes na DE2-115.')
Q.qa(37,'Que evidências vocês têm?','A revisão local registrou 16 suítes GHDL aprovadas; há relatório de 35 simulações ModelSim e relatórios Quartus recebidos. Mostrem logs e versões. Para o hardware, apresentem apenas fotos e resultados que vocês coletaram; a conversa não registra aprovação final da placa.','entrega/evidencias/ghdl-2026-11-25.log; summary.txt; docs/progresso.md.')
Q.qa(38,'A demo testa todas as instruções?','Ela testa ADDI, ADD, SUB, BEQ, JMP, ST e LD. Os outros programas ampliam a cobertura para AND, OR, SLT, BNE e cenários de limite. top_memory testa overflow, persistência e falha. Nenhuma quantidade finita de testes prova ausência de todo defeito.','p1_arith.mif a p4_r0_jump.mif; tests/top_memory.mif.')
Q.qa(39,'Por que conferir o hash do SOF?','Para identificar a imagem exata carregada. O mesmo nome pode conter outra compilação. SHA-256 ajuda a verificar integridade e correspondência com o pacote; não demonstra correção funcional do hardware.','entrega/placa/SHA256.txt.')
Q.qa(40,'Quais limitações vocês reconhecem?','RAM de 1024 palavras, imediato de 6 bits, conjunto de instruções pequeno, sem HALT na ISA, sem pipeline, cache ou sistema de interrupções implementados nestes fontes. Flags não são registradores de estado visíveis por instruções. A adequação ao trabalho depende do enunciado do professor.','docs/isa.md; control_unit.vhd; datapath.vhd.')
Q.box('<b>Treino de 5 minutos:</b> uma pessoa explica a hierarquia; outra decodifica 5203; outra acompanha LD; outra mostra 0003 no RDM e explica o laço. Depois troquem as funções. Em cada resposta, apontem o arquivo ou o indicador que sustenta a explicação.')
Q.save()

# DOCUMENTO 3
F=Guide('03 - Guia dos arquivos do projeto.pdf','CPU 16 bits | Guia dos arquivos do projeto')
F.page('1. Mapa do repositório','O que abrir para entender, simular, compilar e programar')
F.p('O projeto separa o circuito sintetizável, as imagens de memória, os testes e a entrega. Há 17 fontes VHDL de síntese listados no QSF. Os arquivos tb_*.vhd pertencem à simulação e não entram no hardware do projeto Quartus.')
F.table([['Local / extensão','Para que serve'],['Raiz: *.vhd','Circuito da CPU e interface da placa. Páginas 2–4 deste guia.'],['Raiz: *.mif','Conteúdo inicial da RAM. Página 5.'],['cpu_de2_115.qpf / .qsf / .sdc','Abrir/configurar o projeto Quartus e definir timing. Página 5.'],['tests/','Testbenches, runners e imagem de teste do top. Páginas 6–7.'],['docs/','ISA, arquitetura, validação e histórico. Página 8.'],['entrega/','PDFs, apresentação, imagens SOF, pacotes ZIP e evidências. Página 9.'],['.build/','Resultados temporários/gerados; pode surgir ao compilar ou simular. Não é fonte do circuito.']],[190,317])
F.h('Caminhos para cada tarefa')
F.p('<b>Programar:</b> abra o Programmer e carregue entrega/placa/demo.sof. <b>Recompilar:</b> abra cpu_de2_115.qpf. <b>Entender a interface:</b> leia top_de2_115.vhd. <b>Entender o programa:</b> leia cpu_test.mif junto de docs/isa.md. <b>Rodar a regressão local:</b> execute tests/run_all.sh com GHDL disponível.')
F.h('Hierarquia de instâncias')
F.box('top_de2_115<br/>• board_controls: reset, passo e modo<br/>• cpu<br/>&nbsp;&nbsp;• control_unit → decoder<br/>&nbsp;&nbsp;• datapath → PC, IR, banco, extensor, A/B, ULA, ALUOut, REM, RAM e RDM')
F.p('O nome do arquivo ajuda a localizar o bloco, mas a hierarquia real vem das instâncias entity work e dos port maps. Um arquivo de teste pode instanciar os mesmos blocos com sinais artificiais para verificar seus resultados.')
F.p('Este inventário descreve os arquivos funcionais e de suporte presentes na revisão de 25/11. Logs gerados repetem o papel indicado para sua família. Os arquivos ocultos de Git pertencem ao controle de versão e não são enviados à FPGA.')

F.page('2. Os módulos que coordenam','Quatro fontes conectam operação e interface')
for name,text in [
('top_de2_115.vhd','É a entidade de topo da placa. Recebe CLOCK_50, KEY e SW; instancia board_controls e cpu. Usa SW3..1 para escolher o dado exibido e converte nibbles em segmentos. HEX7..4 mostra PC; HEX3..0 mostra o dado; LEDR/LEDG mostram valores e status. É o primeiro arquivo para entender o que aparece na bancada.'),
('board_controls.vhd','Converte botões/switch de modo em reset, clock_enable e running. Implementa sincronizadores, filtro de repique e controle de uma pressão por passo. O parâmetro debounce_cycles vale 500000 por padrão. KEY0 tem asserção assíncrona e liberação sincronizada. Não executa instruções nem calcula resultados da CPU.'),
('cpu.vhd','Integra control_unit e datapath. Encaminha controles ao caminho de dados, devolve opcode/Zero ao controle e liga address_fault ao halt. Exporta monitores de PC, IR, operandos, escrita e memória. Sua interface facilita testar a CPU sem depender da placa.'),
('control_unit.vhd','Contém a máquina de estados: FETCH0, FETCH1, DECODE, EXEC, ADDR, READ_MEM, LATCH_RDM, WRITE_MEM, CMP e WB. Define habilitações e seletores em cada etapa. Com clock_enable=0 retém o estado; com halt=1 interrompe o avanço e desativa os controles de operação. Instancia decoder para interpretar o opcode.')]:
 F.h(name); F.p(text)
F.box('<b>Pergunta para orientar a leitura:</b> se KEY1 foi pressionado e nada mudou, comece nos controles; se a CPU avançou para o estado errado, examine o controle; se o cálculo está errado, acompanhe o datapath e a ULA.')

F.page('3. Cálculo, seleção e banco','Cinco arquivos explicam de onde vêm os valores')
for name,text in [
('datapath.vhd','Conecta os componentes de armazenamento e cálculo. Extrai campos da instrução; seleciona leituras do banco, operando imediato, endereço de RAM e retorno ao banco. Calcula PC+1 e destinos de salto. Também verifica endereço fora da faixa e bloqueia efeitos inválidos antes do truncamento para 10 bits. É o arquivo central para seguir o caminho de um dado.'),
('decoder.vhd','Traduz o opcode em propriedades: operação da ULA, uso de imediato, tipo de acesso, salto, comparação e seleção do retorno. Não guarda estado. A unidade de controle usa essas propriedades na etapa apropriada. Opcode da instrução tem 4 bits; seletor interno da ULA tem 3.'),
('alu.vhd','Calcula ADD, SUB, AND, OR e SLT signed de 16 bits. Produz resultado, Zero e Overflow. Não recebe clock: é combinacional. Overflow pertence às operações signed de soma/subtração; os resultados permanecem truncados em 16 bits. Seletores internos não usados retornam zero.'),
('register_file.vhd','Banco R0–R7 com duas leituras combinacionais independentes e uma escrita habilitada na subida. Armazena apenas R1–R7, pois R0 é constante zero. Reset zera os sete registradores graváveis. Os endereços de leitura/escrita têm 3 bits.'),
('immediate_extender.vhd','Converte imediato de 6 para 16 bits por extensão de sinal: copia o bit 5 para os dez bits superiores. Exemplo: 111111 vira FFFF. Não precisa de clock, reset ou armazenamento.')]:
 F.h(name); F.p(text)

F.page('4. Registradores e RAM','Oito arquivos preservam valores entre as etapas')
F.table([['Arquivo','O que armazena e quando muda'],['pc.vhd','PC de 16 bits. Carrega next_pc na subida quando pc_write=1. Reset zera. O incremento é calculado fora do módulo.'],['instruction_register.vhd','IR de 16 bits. Captura instruction_in quando ir_write=1; mantém a palavra durante a execução. Reset zera.'],['reg_a.vhd','Operando A de 16 bits. Captura com write_enable; retém entre DECODE e as etapas seguintes. Reset zera.'],['reg_b.vhd','Operando B de 16 bits. Também pode guardar o dado de ST, escolhido por read_addr2_sel. Reset zera.'],['alu_out.vhd','Resultado da ULA de 16 bits. Captura quando habilitado. Não guarda Zero nem Overflow. Reset zera.'],['memory_address_register.vhd','REM de 10 bits. Guarda endereço de acesso de dados, já validado no datapath. Reset zera.'],['memory_data_register.vhd','RDM de 16 bits. Guarda o dado lido da RAM para uso posterior, inclusive no WB de LD. Reset zera.'],['memory.vhd','RAM 1024×16. Escrita e leitura síncronas. Escrita tem prioridade e impede leitura na mesma borda; saída retém o último valor quando não lê. Não possui reset.']],[190,317])
F.h('Duas formas de inicialização no mesmo memory.vhd')
F.p('Na simulação, load_mif lê o subconjunto de formato MIF usado pelo projeto. As diretivas synthesis translate_off/on excluem esse leitor de texto da síntese. No Quartus, o atributo ram_init_file associa o MIF à RAM inferida. O hardware não abre um arquivo de texto do computador durante a execução.')
F.p('A separação entre RAM e RDM explica por que LD precisa de READ_MEM e LATCH_RDM em ciclos distintos. Na borda da leitura, a saída registrada da RAM atualiza depois da amostragem; RDM captura esse valor em uma borda posterior.')

F.page('5. Configuração e imagens de memória','Arquivos que escolhem a placa e o programa inicial')
F.table([['Arquivo','Função'],['cpu_de2_115.qpf','Entrada do projeto Quartus; identifica a revisão cpu_de2_115 e versão de referência 20.1.'],['cpu_de2_115.qsf','Configuração ativa: Cyclone IV E EP4CE115F29C7, top, 17 fontes, MIF, SDC, pinos, padrões elétricos e saída .build/quartus.'],['cpu_de2_115.sdc','Clock de 20 ns (50 MHz), incerteza e exceções para entradas assíncronas e indicadores. Base da análise de timing.'],['DE2_115_pin_assignments.qsf','Referência de pinagem fornecida para a placa. Serve para conferência; as atribuições usadas pelo projeto estão no QSF ativo.'],['cpu_test.mif','Programa da demo: contador, soma três vezes, ST/LD no endereço 0010 e JMP final em 0009.'],['memory_test.mif','Padrões usados para validar o módulo de memória e sua inicialização. Não é a demo da CPU.'],['datapath_test.mif','Imagem de apoio ao teste do datapath dirigido por controles artificiais.'],['p1_arith.mif','ADDI, ADD, SUB, AND, OR, SLT e JMP. Resultados distintos para conferir operações.'],['p2_limit.mif','Imediatos -32/+31 e comparações, com soma que não causa overflow signed.'],['p3_mem.mif','LD/ST, soma 7FFF+1, armazenamento de 8000 e releitura.'],['p4_r0_jump.mif','R0, BEQ/BNE tomados e não tomados, laço negativo, opcode inválido e JMP.'],['tests/top_memory.mif','Programa especial: lê 7FFF, soma 1, grava no mesmo endereço e salta para 0400 para provocar falha.']],[190,317])
F.p('Os SOF prontos já incorporam a imagem de memória escolhida na geração. Trocar um MIF no disco não muda um SOF existente. Para uma variante, gere uma nova imagem seguindo entrega/LEIA-ME.md ou faça compilação completa em uma cópia separada.')

F.page('6. Testbenches: componentes','Arquivos VHDL que verificam o circuito sem programar a placa')
F.p('Um testbench gera entradas, espera eventos e usa assertions para conferir resultados. Ele não entra na lista VHDL_FILE do QSF. A terminação com PASS vale para os cenários executados, não para todas as combinações possíveis de uma CPU.')
F.table([['Arquivo em tests/','O que verifica'],['tb_register_file.vhd','Leituras, escrita, habilitação, reset e proteção de R0.'],['tb_instruction_register.vhd','Captura/retenção da instrução, bordas e reset.'],['tb_pc.vhd','Carga de next_pc, retenção, habilitação e reset; PC não incrementa sozinho.'],['tb_immediate_extender.vhd','As 64 combinações de imediato de 6 bits e extensão signed.'],['tb_instruction_formats.vhd','Separação dos campos R/I/J, captura no IR e imediato. Alguns opcodes são padrões sintéticos de formato.'],['tb_alu.vhd','ADD/SUB/AND/OR/SLT, Zero, Overflow e seletores não usados.'],['tb_alu_registers.vhd','Integração A/B, ULA e ALUOut; habilitações, retenção e ordem das bordas.'],['tb_memory.vhd','Inicialização, leitura/escrita, prioridade, retenção e sequência REM/RAM/RDM.'],['tb_datapath.vhd','Caminho de dados dirigido por controles de teste: seleciona operações e confere as saídas.'],['tb_control_unit.vhd','Sequência de estados e sinais de controle para classes de instrução, desvios e reset.']],[200,307])
F.p('Os scripts run_register_file.sh, run_instruction_register.sh, run_pc.sh, run_immediate_extender.sh, run_instruction_formats.sh, run_alu.sh, run_alu_registers.sh, run_memory.sh, run_datapath.sh e run_control_unit.sh preparam e executam os testes de mesmo nome no GHDL.')
F.box('<b>Exemplo:</b> run_alu.sh é o comando de execução; tb_alu.vhd contém os estímulos e as verificações; alu.vhd é o circuito sob teste. Os três papéis não são intercambiáveis.')

F.page('7. Testbenches: CPU e placa','Testes integrados e scripts de execução')
F.table([['Arquivo em tests/','Função'],['tb_cpu.vhd','Executa a demo integrada, confere escritas e repete por reset sem destruir o código.'],['tb_program.vhd','Testbench parametrizado para p1–p4; acompanha resultados e caminhos de execução.'],['tb_address_fault.vhd','Exercita endereços inválidos/válidos, bloqueio de efeitos, retenção da falha e reset.'],['tb_cpu_enable.vhd','Compara execução contínua e pausada; confere retenção e comportamento com reset/falha.'],['tb_board_controls.vhd','Testa sincronização/filtro digital, pressão mantida, troca de modo, reset e rearmamento.'],['tb_top_de2_115.vhd','Integra controles, CPU e indicadores; verifica demo, falha, dígitos e cenário de memória/overflow.'],['run_cpu.sh / run_programs.sh','Executam a demo / quatro programas com GHDL.'],['run_address_fault.sh','Cria imagens dos cenários de endereço em pasta temporária e executa os testes.'],['run_cpu_enable.sh','Executa os cenários de pausa/passo da CPU.'],['run_board_controls.sh','Executa controles com parâmetros de filtro reduzidos para simulação.'],['run_top_de2_115.sh','Executa quatro casos do top, incluindo MIFs temporários para falha e dígitos.'],['run_all.sh','Orquestra as 16 suítes GHDL; interrompe se algum runner retornar erro.'],['run_modelsim.do','Fluxo Tcl para ModelSim: compila, prepara imagens, roda casos isolados e verifica probes de sucesso/falha/timeout.'],['README.md','Instruções e histórico de cobertura; algumas contagens antigas descrevem etapas anteriores.']],[205,302])
F.p('Contagem atual documentada: 16 suítes no runner GHDL; 35 simulações na evidência ModelSim. As contagens não são comparáveis uma a uma: uma suíte pode executar vários cenários. Use o runner atual e seu log para saber o que rodou.')

